CREATE OR REPLACE FUNCTION sync_note_customer() RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.note IS NOT NULL THEN
            NEW.customer_note := NEW.note;
        END IF;
        IF NEW.customer_note IS NOT NULL THEN
            NEW.note := NEW.customer_note;
        END IF;
    ELSIF TG_OP = 'UPDATE' THEN
        IF NEW.note IS DISTINCT FROM OLD.note THEN
            NEW.customer_note := NEW.note;
        END IF;
        IF NEW.customer_note IS DISTINCT FROM OLD.customer_note THEN
            NEW.note := NEW.customer_note;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
